   510              }
   511          } else {
   512            /* 2-byte code */
   513              *len = 2;
   514              val = (cur[0] & 0x1f) << 6;
   515              val |= cur[1] & 0x3f;
   516              if (val < 0x80)
   517                  goto encoding_error;
   518          }
   519          if (!IS_CHAR(val)) {
